    Predicate<Trade> isActive = Trade::active;
    Predicate<Trade> isLarge = t -> t.amount().compareTo(new BigDecimal("100000")) > 0;
    Predicate<Trade> isActiveLarge = isActive.and(isLarge);  // compose predicates!

    // Function<T,R>: T → R (transformation)
    Function<Trade, String> toSymbol = Trade::symbol;
    Function<Trade, BigDecimal> toAmount = Trade::amount;

    // Consumer<T>: T → void (side effect)
    Consumer<Trade> logTrade = t -> System.out.println("Processing: " + t.id());

    // Supplier<T>: () → T (factory)
    Supplier<List<Trade>> emptyList = List::of;

    // BinaryOperator<T>: (T,T) → T (reduce)
    BinaryOperator<BigDecimal> sumAmounts = BigDecimal::add;

    public BigDecimal totalActiveLargeTrades(List<Trade> trades) {
        return trades.stream()
            .filter(isActiveLarge)           // Predicate
            .peek(logTrade)                  // Consumer (debug only!)
            .map(toAmount)                   // Function
            .reduce(BigDecimal.ZERO, sumAmounts);  // BinaryOperator
    }
}
