// ─── File: .../service/TradePipelineService.java ───
package com.bank.pipeline.service;

import java.math.BigDecimal;
import java.util.List;
import java.util.function.*;

record Trade(String id, String symbol, BigDecimal price, int qty, String status) {
    BigDecimal amount() { return price.multiply(BigDecimal.valueOf(qty)); }
    boolean isActive() { return "ACTIVE".equals(status); }
}

public class TradePipelineService {

    // Predicate<T>: T → boolean — FILTERING
    Predicate<Trade> isActive = Trade::isActive;
    Predicate<Trade> isLargeTrade = t -> t.amount().compareTo(new BigDecimal("50000")) > 0;

    // Function<T,R>: T → R — TRANSFORMATION
    Function<Trade, String> toSymbol = Trade::symbol;
    Function<Trade, BigDecimal> toAmount = Trade::amount;
    Function<Trade, String> toSummary = t -> t.symbol() + ": Rs." + t.amount();

    // Consumer<T>: T → void — SIDE EFFECTS
    Consumer<Trade> logTrade = t -> System.out.println("LOG: " + t.id() + " " + t.symbol());
    Consumer<Trade> notifyTrade = t -> System.out.println("NOTIFY: " + t.id() + " settled");
    Consumer<Trade> logAndNotify = logTrade.andThen(notifyTrade);  // compose!

    // Supplier<T>: () → T — LAZY FACTORY
    Supplier<BigDecimal> defaultThreshold = () -> new BigDecimal("100000");
    Supplier<List<Trade>> emptyTradeList = List::of;

    // BinaryOperator<T>: (T,T) → T — REDUCE
    BinaryOperator<BigDecimal> sum = BigDecimal::add;

    // Complete pipeline using all four:
    public BigDecimal processActiveLargeTrades(List<Trade> trades) {
        return trades.stream()
            .filter(isActive)                    // Predicate: keep active
            .filter(isLargeTrade)                // Predicate: keep large
            .peek(logAndNotify)                  // Consumer: log + notify (debug)
            .map(toAmount)                       // Function: Trade → BigDecimal
            .reduce(BigDecimal.ZERO, sum);       // BinaryOperator: sum all
    }

    // UnaryOperator<T>: T → T (same type)
    UnaryOperator<BigDecimal> applyBrokerage = amount -> amount.multiply(new BigDecimal("0.999"));
    // Used in: List.replaceAll(applyBrokerage) — modifies each element in-place
}
