            return amt -> amt.signum() >= 0;
        }
    }

    @Test
    void staticFactoryCalledOnInterfaceName() {
        Validator<BigDecimal> v = Validator.nonNegativeAmount();  // not via instance

        assertThat(v.valid(new BigDecimal("50000"))).isTrue();
        assertThat(v.valid(new BigDecimal("-1"))).isFalse();
