package com.bank.stream.service;

import java.math.BigDecimal;
import java.util.List;
import java.util.stream.Stream;

record Trade(String id, String symbol, BigDecimal amount, String status) {}

public class TradeStreamService {

    public void demonstrateLaziness(List<Trade> trades) {
        // LAZY: this line does NOTHING — no filtering happens yet!
        Stream<Trade> pipeline = trades.stream()
            .filter(t -> {
                System.out.println("Filtering: " + t.id()); // proves laziness
                return "SETTLED".equals(t.status());
            })
            .map(t -> {
                System.out.println("Mapping: " + t.id());
                return t;
            });
        // NOTHING printed yet! Pipeline is just a PLAN.

        // TERMINAL: triggers evaluation — NOW filtering + mapping execute
        long count = pipeline.count();
        // Prints: Filtering: TRD-001, Mapping: TRD-001, Filtering: TRD-002, ...
        // Each element passes through filter → map → count ONE AT A TIME (not all-filter-then-all-map)

        // REUSE: stream is consumed — cannot use again!
        // pipeline.toList(); // IllegalStateException: stream has already been operated upon!
    }

    // Intermediate (lazy): filter, map, sorted, distinct, peek, limit, skip, flatMap, takeWhile, dropWhile
    // Terminal (trigger): collect, forEach, reduce, count, min, max, findFirst, findAny, anyMatch, allMatch, noneMatch, toArray, toList
    // Short-circuiting terminal: findFirst, findAny, anyMatch, allMatch, noneMatch, limit
}
