package com.bank.valuation.service;

import java.math.BigDecimal;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;

record Holding(String symbol, BigDecimal marketValue) {}

public class PortfolioValuationService {

    // GOOD: CPU-bound, large dataset, no shared mutable state
    public BigDecimal totalValueParallel(List<Holding> holdings) {
        return holdings.parallelStream()
            .map(Holding::marketValue)
            .reduce(BigDecimal.ZERO, BigDecimal::add);
        // Splits across ForkJoinPool threads, each reduces a chunk, combines results
    }

    // BAD: shared mutable state → race condition!
    public void unsafeParallel(List<Holding> holdings) {
        // AtomicInteger is thread-safe but demonstrates the pitfall concept:
        final BigDecimal[] total = {BigDecimal.ZERO}; // NOT thread-safe!
        holdings.parallelStream().forEach(h -> {
            total[0] = total[0].add(h.marketValue()); // RACE CONDITION! Lost updates!
        });
        // FIX: use reduce() or collect() — they handle parallelism safely
    }

    // BAD: small collection — overhead > benefit
    public BigDecimal dontParallelizeSmall(List<Holding> holdings) {
        if (holdings.size() < 10000) {
            return holdings.stream().map(Holding::marketValue)
                .reduce(BigDecimal.ZERO, BigDecimal::add); // sequential is faster!
        }
        return holdings.parallelStream().map(Holding::marketValue)
            .reduce(BigDecimal.ZERO, BigDecimal::add);
    }
}
