package com.bank.analytics.service;

import java.math.BigDecimal;
import java.util.*;
import java.util.stream.Collectors;

record Customer(String id, String name, List<Trade> trades) {}
record Trade(String id, BigDecimal amount) {}

public class TradeAnalyticsService {

    // MAP: one-to-one (Trade → amount)
    public List<BigDecimal> getAmounts(List<Trade> trades) {
        return trades.stream()
            .map(Trade::amount)          // Trade → BigDecimal
            .toList();
    }

    // FLATMAP: one-to-many + flatten (Customer → Trades → flat stream)
    public List<Trade> getAllTrades(List<Customer> customers) {
        // map gives: Stream<List<Trade>> — NESTED!
        // flatMap gives: Stream<Trade> — FLAT!
        return customers.stream()
            .flatMap(customer -> customer.trades().stream())  // flatten
            .toList();
    }

    // REDUCE: aggregate into single value (sum all amounts)
    public BigDecimal totalAmount(List<Trade> trades) {
        return trades.stream()
            .map(Trade::amount)
            .reduce(BigDecimal.ZERO, BigDecimal::add);  // identity + accumulator
    }

    // REDUCE with 3 params (for parallel): identity, accumulator, combiner
    public BigDecimal totalAmountParallel(List<Trade> trades) {
        return trades.parallelStream()
            .map(Trade::amount)
            .reduce(BigDecimal.ZERO,    // identity
                    BigDecimal::add,    // accumulator (within thread)
                    BigDecimal::add);   // combiner (merge thread results)
    }
}
