package com.bank.lookup.service;

import java.math.BigDecimal;
import java.util.Optional;

record Account(String id, String holderName, BigDecimal balance, String linkedAccountId) {}

interface AccountRepository {
    Optional<Account> findById(String id);
}

public class AccountLookupService {

    private final AccountRepository accountRepo;
    public AccountLookupService(AccountRepository accountRepo) { this.accountRepo = accountRepo; }

    // orElseThrow: required value — throw if absent
    public Account getAccountOrFail(String id) {
        return accountRepo.findById(id)
            .orElseThrow(() -> new IllegalArgumentException("Account not found: " + id));
    }

    // orElse: static default
    public String getHolderName(String id) {
        return accountRepo.findById(id)
            .map(Account::holderName)
            .orElse("UNKNOWN");
    }

    // orElseGet: LAZY default (compute only if absent — saves cost)
    public BigDecimal getBalance(String id) {
        return accountRepo.findById(id)
            .map(Account::balance)
            .orElseGet(() -> fetchBalanceFromLedger(id)); // only called if absent!
    }

    // ifPresent: side effect only if present
    public void notifyIfExists(String id) {
        accountRepo.findById(id)
            .ifPresent(acc -> System.out.println("Notify: " + acc.holderName()));
    }

    // map + filter: chain transformations
    public Optional<BigDecimal> getActiveBalance(String id) {
        return accountRepo.findById(id)
            .filter(acc -> acc.balance().compareTo(BigDecimal.ZERO) > 0)  // filter
            .map(Account::balance);  // transform
    }

    // flatMap: avoid Optional<Optional<T>> — when map returns Optional
    public Optional<Account> getLinkedAccount(String id) {
        return accountRepo.findById(id)
            .flatMap(acc -> accountRepo.findById(acc.linkedAccountId()));
        // map would give: Optional<Optional<Account>> — nested!
        // flatMap gives: Optional<Account> — flat!
    }

    // BAD: .get() without check — code smell!
    // account.get().getBalance(); // NoSuchElementException if empty!
    // FIX: always use orElse/orElseThrow/ifPresent/map

    // BAD: Optional as field — not Serializable, extra allocation
    // class Account { Optional<String> nickname; } // ANTI-PATTERN!
    // FIX: use nullable field + Optional return method

    private BigDecimal fetchBalanceFromLedger(String id) { return BigDecimal.ZERO; }
}
