package com.bank.ref.service;

import java.math.BigDecimal;
import java.util.List;
import java.util.function.*;

record Trade(String id, String symbol, BigDecimal amount) {}

public class MethodReferenceDemo {

    // TYPE 1: Static method reference
    // ClassName::staticMethod → equivalent to (x) -> ClassName.staticMethod(x)
    Function<String, BigDecimal> parseAmount = BigDecimal::new;  // String → BigDecimal
    // Lambda: s -> new BigDecimal(s) — but that's actually constructor ref (Type 4)

    // TYPE 2: Instance method of specific object
    // instance::method → equivalent to (x) -> instance.method(x)
    Consumer<String> printer = System.out::println;  // prints to console
    // Lambda: s -> System.out.println(s)

    // TYPE 3: Instance method of arbitrary object (most common in streams!)
    // ClassName::instanceMethod → first param becomes 'this'
    Function<Trade, BigDecimal> getAmount = Trade::amount;  // t -> t.amount()
    Function<Trade, String> getSymbol = Trade::symbol;       // t -> t.symbol()
    Predicate<String> isEmpty = String::isEmpty;              // s -> s.isEmpty()

    // TYPE 4: Constructor reference
    // ClassName::new → equivalent to (args) -> new ClassName(args)
    Function<String, StringBuilder> sbFactory = StringBuilder::new;  // s -> new StringBuilder(s)
    Supplier<List<Trade>> listFactory = java.util.ArrayList::new;    // () -> new ArrayList()

    // All four in a stream pipeline:
    public void processAll(List<Trade> trades) {
        trades.stream()
            .map(Trade::amount)          // Type 3: instance of arbitrary object
            .map(BigDecimal::toString)   // Type 3: BigDecimal → String
            .forEach(System.out::println); // Type 2: instance of specific object
    }
}
